t.script:
(function () {
    function closeAll() {
        document.querySelectorAll('.tc-benefits-popup.open').forEach(function (p) { p.classList.remove('open'); });
    }
    function init() {
        /* Click on card image area → toggle popup */
        document.querySelectorAll('.sr-tier-visual').forEach(function (visual) {
            visual.addEventListener('click', function (e) {
                /* close button inside popup */
                if (e.target.closest('.tc-pop-close')) {
                    closeAll();
                    return;
                }
                /* clicking inside an already-open popup → do nothing (allow scroll) */
                if (e.target.closest('.tc-benefits-popup')) return;
                e.stopPropagation();
                var popup = visual.querySelector('.tc-benefits-popup');
                if (!popup) return;
                var isOpen = popup.classList.contains('open');
                closeAll();
                if (!isOpen) popup.classList.add('open');
            });
        });
        document.addEventListener('click', closeAll);
        document.addEventListener('keydown', function (e) {
            if (e.key === 'Escape') closeAll();
        });
    }
    if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', init); }
    else { init(); }
})();
